import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

/**
 * Unit tests for LongSerializer#serialize
 */
public class LongSerializer_serialize_TriageGen1Test {

    private NumberSerializers.LongSerializer serializer;
    private JsonGenerator gen;
    private SerializerProvider provider;

    @Before
    public void setUp() {
        serializer = new NumberSerializers.LongSerializer();
        gen = mock(JsonGenerator.class);
        provider = mock(SerializerProvider.class);
    }

    @Test
    public void testSerialize_WithValidLong() throws IOException {
        // Arrange
        Long value = 12345L;

        // Act
        serializer.serialize(value, gen, provider);

        // Assert
        verify(gen, times(1)).writeNumber(value.longValue());
    }

    @Test
    public void testSerialize_WithIntegerAsLong() throws IOException {
        // Since the method casts to (Long), passing an Integer will throw ClassCastException.
        // This test ensures we understand the strict requirement of the implementation.
        Object value = 123; // Integer, not Long

        try {
            serializer.serialize(value, gen, provider);
        } catch (ClassCastException e) {
            // Expected behavior based on the code: ((Long) value)
        }

        verify(gen, never()).writeNumber(anyLong());
    }

    @Test(expected = ClassCastException.class)
    public void testSerialize_WithWrongType_ThrowsClassCastException() throws IOException {
        // Arrange
        Object value = "not a long";

        // Act
        serializer.serialize(value, gen, provider);

        // Assert - handled by expected annotation
    }

    @Test(expected = NullPointerException.class)
    public void testSerialize_WithNullValue_ThrowsNullPointerException() throws IOException {
        // Arrange
        Object value = null;

        // Act
        serializer.serialize(value, gen, provider);

        // Assert - handled by expected annotation
    }

    @Test(expected = IOException.class)
    public void testSerialize_WhenGeneratorThrowsIOException() throws IOException {
        // Arrange
        Long value = 100L;
        doThrow(new IOException("Simulated IO Error")).when(gen).writeNumber(anyLong());

        // Act
        serializer.serialize(value, gen, provider);

        // Assert - handled by expected annotation
    }
}
